using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
internal sealed class DofusOverlay:Window {
 readonly MainForm host;readonly Store store;readonly Func<TougliDocument> document;readonly Action open;readonly Action<int,bool> move;readonly Action toggle;readonly Action<TougliStep> travel;readonly DispatcherTimer timer;string signature="";bool stopped;ThemePalette palette;
 internal DofusOverlay(MainForm owner,Store data,Func<TougliDocument> source,Action openPage,Action<int,bool> navigation,Action validation,Action<TougliStep> copy){host=owner;store=data;document=source;open=openPage;move=navigation;toggle=validation;travel=copy;Title="Compagnon Dofus";Width=data.Value.dofus.width;Height=data.Value.dofus.height;MinWidth=300;MinHeight=300;MaxWidth=1400;MaxHeight=1400;WindowStyle=WindowStyle.None;AllowsTransparency=true;ResizeMode=ResizeMode.CanResizeWithGrip;Background=Brushes.Transparent;ShowInTaskbar=false;Topmost=data.Value.dofus.topmost;timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=delegate{RefreshView();};Loaded+=delegate{if(!host.IsPreview){if(store.Value.dofus.positionSaved){Left=store.Value.dofus.left;Top=store.Value.dofus.top;}else{Left=SystemParameters.WorkArea.Right-Width-24;Top=SystemParameters.WorkArea.Top+40;}KeepVisible();timer.Start();}};Closed+=delegate{stopped=true;timer.Stop();if(!host.IsPreview&&!host.IsDisposed)try{PersonalWorkflows.Change(store,()=>{var o=store.Value.dofus;o.width=Math.Max(300,Math.Min(1400,Width));o.height=Math.Max(300,Math.Min(1400,Height));o.left=Left;o.top=Top;o.positionSaved=true;});}catch{}};RefreshView();}
 void KeepVisible(){double scale=1;using(var g=System.Drawing.Graphics.FromHwnd(IntPtr.Zero))scale=g.DpiX/96.0;var areas=System.Windows.Forms.Screen.AllScreens.Select(s=>new Rect(s.WorkingArea.X/scale,s.WorkingArea.Y/scale,s.WorkingArea.Width/scale,s.WorkingArea.Height/scale)).ToList();var point=WidgetModel.Clamp(new Point(Left,Top),new Size(Width,Height),areas);var area=areas.FirstOrDefault(a=>a.Contains(point));if(area.Width>0){Width=Math.Max(300,Math.Min(Width,area.Width-16));Height=Math.Max(300,Math.Min(Height,area.Height-16));}point=WidgetModel.Clamp(point,new Size(Width,Height),areas);Left=point.X;Top=point.Y;}
 Brush B(Color c){return new SolidColorBrush(c);}
 TextBlock T(string text,double size=12,bool muted=false){return new TextBlock{Text=text,FontSize=size,Foreground=B(muted?palette.Muted:palette.Ink),TextWrapping=TextWrapping.Wrap};}
 Button Btn(string text,Action action,bool primary=false){var b=new Button{Content=text,Margin=new Thickness(0,0,6,7),Padding=new Thickness(10,8,10,8),Background=B(primary?palette.Accent:palette.Surface),Foreground=B(primary?Appearance.TextOn(palette.Accent):palette.Ink)};b.Click+=delegate{if(!host.IsDisposed&&host.Enabled)action();};return b;}
 internal void RefreshView(){if(stopped)return;var data=store.Value;bool hidden=data.settings.PrivacyMode;var c=DofusCompanion.Character(data);var doc=hidden?null:document();var step=doc==null?null:DofusCompanion.Current(data,doc);var p=DofusCompanion.Find(data,c);string sig=hidden+"/"+(c==null?"":c.id)+"/"+(doc==null?"":doc.Hash)+"/"+(step==null?"":step.Key)+"/"+(p==null?"":p.done.Count+"/"+(step==null?false:p.done.Contains(step.Key)))+"/"+new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(data.settings.Appearance)+"/"+data.dofus.topmost;if(sig==signature)return;signature=sig;palette=Appearance.Palette(data.settings.Appearance);Topmost=data.dofus.topmost;host.StyleDesktopWidget(this);var frame=new Border{Background=B(palette.Card),BorderBrush=B(palette.Border),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),Padding=new Thickness(17)};Content=frame;var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});frame.Child=grid;var header=new DockPanel{Margin=new Thickness(0,0,0,12)};var close=Btn("×",Close);DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);var label=T(hidden?"Mode discret":"COMPAGNON DOFUS",11,true);label.Cursor=Cursors.SizeAll;label.MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){if(e.LeftButton==MouseButtonState.Pressed&&!host.IsPreview){DragMove();KeepVisible();}};header.Children.Add(label);grid.Children.Add(header);
  var body=new StackPanel();var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);grid.Children.Add(scroll);var footer=new StackPanel{Margin=new Thickness(0,12,0,0)};Grid.SetRow(footer,2);grid.Children.Add(footer);if(hidden){body.Children.Add(T("Votre progression est masquée.",16));return;}
  if(c==null||doc==null||step==null){body.Children.Add(T("Reprenez votre aventure.",22));body.Children.Add(T(c==null?"Ajoutez votre personnage dans Mon espace.":"Chargez le parcours choisi depuis le compagnon.",12,true));footer.Children.Add(Btn("Ouvrir le compagnon",open,true));return;}
  body.Children.Add(T(c.name+(c.server==""?"":" · "+c.server),13));body.Children.Add(T(doc.Title,11,true));int done=doc.Steps.Count(s=>p!=null&&p.done.Contains(s.Key));body.Children.Add(T(done+" / "+doc.Steps.Count+" étapes",11,true));var bar=new Grid{Height=4,Background=B(palette.Surface),Margin=new Thickness(0,10,0,14)};bar.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(done,GridUnitType.Star)});bar.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(doc.Steps.Count-done,GridUnitType.Star)});bar.Children.Add(new Border{Background=B(palette.Accent)});body.Children.Add(bar);body.Children.Add(T(step.Section,11,true));var title=T(step.Title,21);title.FontFamily=new FontFamily("Georgia");title.Margin=new Thickness(0,7,0,13);body.Children.Add(title);body.Children.Add(T(step.Details==""?"Les instructions détaillées sont disponibles dans le guide source.":step.Details,12,true));if(step.Resources.Count>0){body.Children.Add(T("Ressources de la quête",11));foreach(var resource in step.Resources.Take(8))body.Children.Add(T(resource.Count+" × "+resource.Name,11,true));if(step.Resources.Count>8)body.Children.Add(T("Toutes les ressources dans Mon espace",10,true));}
  var controls=new WrapPanel();controls.Children.Add(Btn("←",()=>move(-1,false)));var finish=Btn("Terminé →",()=>move(1,true),true);finish.IsEnabled=step.CanComplete;controls.Children.Add(finish);controls.Children.Add(Btn("Suivant",()=>move(1,false)));footer.Children.Add(controls);var links=new WrapPanel();links.Children.Add(Btn("Compagnon",open));links.Children.Add(Btn("Guide détaillé",delegate{if(!host.IsPreview&&!store.Value.settings.PrivacyMode){var url=TougliReader.SafeUrl(step.Url);if(url!="")System.Diagnostics.Process.Start(url);}}));if(step.CanComplete)links.Children.Add(Btn(p!=null&&p.done.Contains(step.Key)?"Annuler ✓":"Valider ✓",toggle));if(step.Coordinates!="")links.Children.Add(Btn("/travel",()=>travel(step)));footer.Children.Add(links);var pin=new CheckBox{Content="Toujours au premier plan",IsChecked=data.dofus.topmost,FontSize=10,Foreground=B(palette.Muted)};pin.Click+=delegate{try{PersonalWorkflows.Change(store,()=>store.Value.dofus.topmost=pin.IsChecked==true);}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message);}signature="";RefreshView();};footer.Children.Add(pin);footer.Children.Add(T("Source : Tougli · progression locale",9,true));
 }
 internal void Render(string path){var element=(FrameworkElement)Content;element.Width=Width;element.Height=Height;element.Measure(new Size(Width,Height));element.Arrange(new Rect(0,0,Width,Height));element.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Width,(int)Height,96,96,PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(path))encoder.Save(file);}
}
